/**
 * LearnIQ Standalone Chart Engine
 * Lightweight, zero-dependency canvas renderer compatible with Chart.js line/bar configs
 */
(function (global) {
    function Chart(canvas, config) {
        if (!canvas) return;
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.config = config || {};
        this.render();
    }

    Chart.prototype.render = function () {
        const ctx = this.ctx;
        const canvas = this.canvas;
        if (!ctx) return;

        const rect = canvas.getBoundingClientRect();
        const width = canvas.width = (rect.width || canvas.clientWidth || 400);
        const height = canvas.height = (rect.height || canvas.clientHeight || 200);

        const data = this.config.data || {};
        const labels = data.labels || [];
        const dataset = (data.datasets && data.datasets[0]) || {};
        const values = dataset.data || [];

        ctx.clearRect(0, 0, width, height);

        const padLeft = 40;
        const padRight = 20;
        const padTop = 20;
        const padBottom = 30;
        const plotWidth = width - padLeft - padRight;
        const plotHeight = height - padTop - padBottom;

        // Draw horizontal grid lines
        const ticks = [0, 25, 50, 75, 100];
        ctx.font = '11px Inter, sans-serif';
        ctx.fillStyle = '#64748b';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.06)';
        ctx.lineWidth = 1;

        ticks.forEach(val => {
            const y = padTop + plotHeight - (val / 100) * plotHeight;
            ctx.beginPath();
            ctx.moveTo(padLeft, y);
            ctx.lineTo(width - padRight, y);
            ctx.stroke();
            ctx.fillText(val + '%', padLeft - 8, y);
        });

        if (values.length === 0) return;

        // Calculate points
        const points = values.map((val, i) => {
            const x = labels.length > 1
                ? padLeft + (i / (labels.length - 1)) * plotWidth
                : padLeft + plotWidth / 2;
            const y = padTop + plotHeight - (Math.min(100, Math.max(0, val)) / 100) * plotHeight;
            return { x, y, val, label: labels[i] };
        });

        // Draw gradient under line
        const gradient = ctx.createLinearGradient(0, padTop, 0, height - padBottom);
        gradient.addColorStop(0, 'rgba(0, 240, 255, 0.25)');
        gradient.addColorStop(1, 'rgba(0, 240, 255, 0.0)');

        ctx.beginPath();
        ctx.moveTo(points[0].x, points[0].y);
        for (let i = 1; i < points.length; i++) {
            ctx.lineTo(points[i].x, points[i].y);
        }
        ctx.lineTo(points[points.length - 1].x, padTop + plotHeight);
        ctx.lineTo(points[0].x, padTop + plotHeight);
        ctx.closePath();
        ctx.fillStyle = gradient;
        ctx.fill();

        // Draw line
        ctx.beginPath();
        ctx.moveTo(points[0].x, points[0].y);
        for (let i = 1; i < points.length; i++) {
            ctx.lineTo(points[i].x, points[i].y);
        }
        ctx.strokeStyle = '#00f0ff';
        ctx.lineWidth = dataset.borderWidth || 3;
        ctx.lineJoin = 'round';
        ctx.stroke();

        // Draw dots and x labels
        ctx.fillStyle = '#94a3b8';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';

        points.forEach(pt => {
            // dot
            ctx.beginPath();
            ctx.arc(pt.x, pt.y, 4, 0, Math.PI * 2);
            ctx.fillStyle = '#00f0ff';
            ctx.fill();
            ctx.strokeStyle = '#0b1120';
            ctx.lineWidth = 2;
            ctx.stroke();

            // x-label
            if (pt.label) {
                ctx.fillStyle = '#64748b';
                ctx.fillText(pt.label, pt.x, height - padBottom + 8);
            }
        });
    };

    Chart.prototype.destroy = function () {};

    global.Chart = Chart;
})(typeof window !== 'undefined' ? window : this);
